-- Esquema de Deuda sueldo Rossy para Supabase (generado desde D1).
create schema if not exists deuda_rossy;
set search_path = deuda_rossy;

CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS salary_tramos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label TEXT NOT NULL, from_date TEXT NOT NULL, to_date TEXT NOT NULL, monto BIGINT NOT NULL, fuente TEXT NOT NULL, sort_order BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL, checked BIGINT NOT NULL, description TEXT NOT NULL, sort_order BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), fecha TEXT NOT NULL, monto BIGINT NOT NULL, nota TEXT, created_at TEXT NOT NULL DEFAULT to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'));
CREATE INDEX IF NOT EXISTS idx_payments_category ON payments(category_id);
